280					border-width: 2px;
281				}
282			}
283			footer {
284				padding-block: 1.5rem;
285				border-top: 1px solid var(--border);
286				font-size: 0.875rem;
287				color: var(--text-secondary);
288				text-align: center;
289			}
290			footer p {
291				margin: 0.5rem 0;
292			}
293			small {
294				display: block;
295			}
296			kbd {
297				background: var(--surface);
298				border: 1px solid var(--border);
299				border-radius: 0.25rem;
300				padding: 0.125rem 0.375rem;
301				font-family: monospace;
302				font-size: 0.875em;
303			}
304			.field {
305				margin-bottom: 1rem;
306			}
307			label {
308				display: block;
309				margin-bottom: 0.5rem;
310				font-weight: 500;
311			}
312			input,
313			textarea {
314				width: 100%;
315				padding: 0.5rem;
316				font: inherit;
317				color: var(--text);
318				background: var(--surface);
319				border: 1px solid var(--border-control);
320				border-radius: 0.25rem;
321			}
322			textarea {
323				resize: vertical;
324			}
325			#form-status {
326				margin: 0;
327			}
328			#form-status:not(:empty) {
329				margin-top: 1rem;
330				padding: 0.75rem 1rem;
331				border-radius: 0.25rem;
332				background: rgba(46, 125, 50, 0.1);
333				color: var(--success);
334				border: 1px solid var(--success);
335			}
336			.form-hint {
337				margin: 0 0 1rem 0;
338				font-size: 0.875rem;
339				color: var(--text-secondary);
340			}
341			.field .form-hint {
342				margin: 0.25rem 0 0 0;
343			}
