351				display: block;
352				color: var(--error);
353				font-size: 0.875rem;
354				font-weight: 500;
355			}
356			.error-message:not(:empty) {
357				margin-top: 0.25rem;
358			}
359			.counter {
360				display: flex;
361				flex-wrap: wrap;
362				gap: 1rem;
363				align-items: center;
364				margin: 1.5rem 0;
