392			@media print {
393				:root {
394					color-scheme: light;
395					--text: #000;
396					--text-secondary: #333;
397					--background: #fff;
398					--surface: #fff;
399					--accent: #000;
400					--border: #999;
401					--border-control: #000;
402					--error: #000;
